32	const Repository: React.FC = () => {
33	  const { '*': repositoryName } = useParams();
34	  const [repository, setRepository] = useState<Repository | null>(null);
35	  const [issues, setIssues] = useState<Issue[]>([]);
36	
37	  useEffect(() => {
38	    api.get(`/repos/${repositoryName}`).then((response) => {
39	      setRepository(response.data);
40	    });
41	    api.get(`/repos/${repositoryName}/issues`).then((response) => {
42	      setIssues(response.data);
43	    });
44	  }, [repositoryName]);
45	
46	  return (
47	    <>
48	      <Header>
49	        <img src={logoImage} alt="Github Explorer" />
50	        <Link to="/">
51	          <FiChevronLeft size={16} color="#3D3D4D" />
52	          <strong>Voltar</strong>
53	        </Link>
54	      </Header>
55	      {repository ? (
56	        <RespositoryInfo>
57	          <header>
58	            <img src={repository.owner.avatar_url} alt="Owner profile avatar" />
59	            <div>
60	              <strong>{repository.full_name}</strong>
61	              <p>{repository.description}</p>
62	            </div>
63	          </header>
64	          <ul>
65	            <li>
66	              <strong>{repository.stargazers_count}</strong>
67	              <span>Stars</span>
68	            </li>
69	            <li>
70	              <strong>{repository.forks_count}</strong>
71	              <span>Forks</span>
72	            </li>
73	            <li>
74	              <strong>{repository.open_issues_count}</strong>
75	              <span>Issues abertos</span>
76	            </li>
77	          </ul>
78	        </RespositoryInfo>
79	      ) : (
80	        <p>Carregando informações.</p>
81	      )}
82	
83	      <Issues>
84	        {issues.map((issue) => (
85	          <a key={issue.id} href={issue.html_url}>
86	            <div>
87	              <strong>{issue.title}</strong>
88	              <p>{issue.user.login}</p>
89	            </div>
90	            <FiChevronRight size={20} />
91	          </a>
92	        ))}
93	      </Issues>
94	
95	      <Footer />
96	    </>
97	  );
98	};
99	
100	export default Repository;
