10	import { Header, RespositoryInfo, Issues, TabsContainer, TabsButtons } from './styles';
11	
12	interface Repository {
13	  full_name: string;
14	  description: string;
15	  owner: {
16	    login: string;
17	    avatar_url: string;
18	  };
19	  stargazers_count: number;
20	  forks_count: number;
21	  open_issues_count: number;
22	}
23	interface Issue {
24	  id: number;
25	  title: string;
26	  html_url: string;
27	  user: {
28	    login: string;
29	  };
30	  created_at: string;
31	}
32	interface PullRequest {
33	  id: number;
34	  title: string;
35	  html_url: string;
36	  user: {
37	    login: string;
38	  };
39	  created_at: string;
40	}
41	
42	const Repository: React.FC = () => {
43	  const { '*': repositoryName } = useParams();
44	  const [repository, setRepository] = useState<Repository | null>(null);
45	  const [issues, setIssues] = useState<Issue[]>([]);
46	  const [pullRequests, setPullRequests] = useState<PullRequest[]>([]);
47	  const [activeTab, setActiveTab] = useState<'issues' | 'pulls'>('issues');
48	
49	  useEffect(() => {
50	    api.get(`/repos/${repositoryName}`).then((response) => {
51	      setRepository(response.data);
52	    });
53	    api.get(`/repos/${repositoryName}/issues`).then((response) => {
54	      setIssues(response.data);
55	    });
56	    api.get(`/repos/${repositoryName}/pulls`).then((response) => {
57	      setPullRequests(response.data);
58	    });
59	  }, [repositoryName]);
60	
61	  const formatDate = (dateString: string) => {
62	    const date = new Date(dateString);
63	    return date.toLocaleDateString('pt-BR', { year: 'numeric', month: '2-digit', day: '2-digit' });
64	  };
65	
66	  return (
67	    <>
68	      <Header>
69	        <img src={logoImage} alt="Github Explorer" />
70	        <Link to="/">
71	          <FiChevronLeft size={16} color="#3D3D4D" />
72	          <strong>Voltar</strong>
73	        </Link>
74	      </Header>
75	      {repository ? (
76	        <RespositoryInfo>
77	          <header>
78	            <img src={repository.owner.avatar_url} alt="Owner profile avatar" />
79	            <div>
80	              <strong>{repository.full_name}</strong>
81	              <p>{repository.description}</p>
82	            </div>
83	          </header>
84	          <ul>
85	            <li>
86	              <strong>{repository.stargazers_count}</strong>
87	              <span>Stars</span>
88	            </li>
89	            <li>
90	              <strong>{repository.forks_count}</strong>
91	              <span>Forks</span>
92	            </li>
93	            <li>
94	              <strong>{repository.open_issues_count}</strong>
95	              <span>Issues abertos</span>
96	            </li>
97	          </ul>
98	        </RespositoryInfo>
99	      ) : (
100	        <p>Carregando informações.</p>
101	      )}
102	
103	      <TabsContainer>
104	        <TabsButtons>
105	          <button
106	            className={activeTab === 'issues' ? 'active' : ''}
107	            onClick={() => setActiveTab('issues')}
108	          >
109	            Issues ({issues.length})
110	          </button>
111	          <button
112	            className={activeTab === 'pulls' ? 'active' : ''}
113	            onClick={() => setActiveTab('pulls')}
114	          >
115	            Pull Requests ({pullRequests.length})
116	          </button>
117	        </TabsButtons>
118	
119	        <Issues>
120	          {activeTab === 'issues' && issues.map((issue) => (
121	            <a key={issue.id} href={issue.html_url}>
122	              <div>
123	                <strong>{issue.title}</strong>
124	                <p>{issue.user.login} em {formatDate(issue.created_at)}</p>
125	              </div>
126	              <FiChevronRight size={20} />
127	            </a>
128	          ))}
129	
130	          {activeTab === 'pulls' && pullRequests.map((pr) => (
131	            <a key={pr.id} href={pr.html_url}>
132	              <div>
133	                <strong>{pr.title}</strong>
134	                <p>{pr.user.login} em {formatDate(pr.created_at)}</p>
135	              </div>
136	              <FiChevronRight size={20} />
137	            </a>
138	          ))}
139	        </Issues>
140	      </TabsContainer>
141	
142	      <Footer />
143	    </>
144	  );
145	};
146	
147	export default Repository;
